CREATE OR REPLACE FUNCTION user_org_ids()
RETURNS SETOF bigint AS $$
BEGIN
  RETURN QUERY SELECT org_id FROM public.org_members WHERE user_id = auth.uid();
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_admin(p_org_id bigint)
RETURNS boolean AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.org_members
    WHERE user_id = auth.uid() AND org_id = p_org_id AND role = 'admin'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_project_member(p_path text)
RETURNS boolean AS $$
DECLARE
  project_id bigint;
  org_id bigint;
BEGIN
  project_id := split_part(p_path, '/', 1)::bigint;
  SELECT org_id INTO org_id FROM public.projects WHERE id = project_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.org_members
    WHERE org_id = org_id AND user_id = auth.uid()
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

CREATE OR REPLACE FUNCTION is_project_admin(p_path text)
RETURNS boolean AS $$
DECLARE
  project_id bigint;
  org_id bigint;
BEGIN
  project_id := split_part(p_path, '/', 1)::bigint;
  SELECT org_id INTO org_id FROM public.projects WHERE id = project_id;
  IF NOT FOUND THEN
    RETURN false;
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.org_members
    WHERE org_id = org_id AND user_id = auth.uid() AND role = 'admin'
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

ALTER TABLE public.org_members ENABLE ROW LEVEL SECURITY;
CREATE POLICY org_members_select ON public.org_members FOR SELECT
USING (org_id = ANY (SELECT * FROM user_org_ids()));
CREATE POLICY org_members_no_actions ON public.org_members
FOR INSERT, UPDATE, DELETE
TO authenticated, anon
USING (FALSE);

ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
CREATE POLICY projects_select ON public.projects FOR SELECT
USING (org_id = ANY (SELECT * FROM user_org_ids()));
CREATE POLICY projects_insert ON public.projects FOR INSERT
WITH CHECK (is_admin(org_id));
CREATE POLICY projects_update ON public.projects FOR UPDATE
USING (is_admin(org_id));
CREATE POLICY projects_delete ON public.projects FOR DELETE
USING (is_admin(org_id));

CREATE POLICY project_files_select ON storage.objects FOR SELECT
TO public
USING (bucket_id = (SELECT id FROM storage.buckets WHERE name = 'project-files') AND is_project_member(path));
CREATE POLICY project_files_insert ON storage.objects FOR INSERT
TO public
WITH CHECK (bucket_id = (SELECT id FROM storage.buckets WHERE name = 'project-files') AND is_project_admin(path));
CREATE POLICY project_files_delete ON storage.objects FOR DELETE
TO public
USING (bucket_id = (SELECT id FROM storage.buckets WHERE name = 'project-files') AND is_project_admin(path));

