create or replace function public.decide_expense(p_expense_id bigint, p_approve boolean)
returns void as $$
declare
  v_department_id bigint;
  v_submitted_by uuid;
  v_is_manager boolean;
  v_caller_id uuid;
begin
  select department_id, submitted_by into v_department_id, v_submitted_by
  from public.expenses
  where id = p_expense_id;

  if not found then
    raise exception 'Expense not found';
  end if;

  if (select status from public.expenses where id = p_expense_id) != 'pending' then
    raise exception 'Expense is not pending';
  end if;

  if current_setting('request.jwt.claims') = 'service_role' then
    v_caller_id := null;
  else
    v_caller_id := auth.uid();
  end if;

  if current_setting('request.jwt.claims') = 'service_role' then
    v_is_manager := true;
  else
    select exists (
      select 1
      from public.department_members
      where user_id = v_caller_id and department_id = v_department_id and is_manager = true
    ) into v_is_manager;
  end if;

  if not v_is_manager then
    raise exception 'Caller is not a manager of the department';
  end if;

  if v_caller_id = v_submitted_by then
    raise exception 'Caller cannot decide their own expense';
  end if;

  update public.expenses
  set status = case when p_approve then 'approved' else 'rejected' end,
      decided_by = case when current_setting('request.jwt.claims') = 'service_role' then null else v_caller_id end
  where id = p_expense_id;
end;
$$ language plpgsql security definer;

