create or replace function enforce_invoice_restrictions()
returns trigger as $$
declare
  is_finance_staff boolean;
begin
  if new.created_by <> old.created_by then
    raise exception 'created_by cannot be changed';
  end if;

  if old.status <> 'draft' and (new.customer <> old.customer or new.amount <> old.amount) then
    raise exception 'Cannot change customer or amount once status is not draft';
  end if;

  if new.status <> old.status then
    select exists (select 1 from public.finance_staff where user_id = auth.uid()) into is_finance_staff;

    if old.status = 'draft' then
      if new.status not in ('sent', 'void', 'paid') then
        raise exception 'Invalid status transition from draft';
      end if;
    elsif old.status = 'sent' then
      if not is_finance_staff then
        raise exception 'Only finance staff can change sent status';
      end if;
      if new.status not in ('paid', 'void') then
        raise exception 'Invalid status transition from sent';
      end if;
    else
      raise exception 'Invalid status transition';
    end if;
  end if;

  return new;
end;
$$ language plpgsql;

create trigger enforce_invoice_restrictions_trigger
before update on public.invoices
for each row
execute function enforce_invoice_restrictions();
