create or replace function can_insert_member(org_id bigint, role text) returns boolean as $$
declare
  user_id uuid := auth.uid();
  is_creator boolean;
  is_owner_or_admin boolean;
  is_owner boolean;
  member_count int;
begin
  select created_by = user_id into is_creator
  from public.orgs
  where id = org_id;

  select count(*) into member_count
  from public.org_members
  where org_id = org_id;

  if is_creator and member_count = 0 and role = 'owner' then
    return true;
  end if;

  select exists (
    select 1
    from public.org_members om
    where om.org_id = org_id and om.user_id = user_id and om.role in ('owner', 'admin')
  ) into is_owner_or_admin;

  if not is_owner_or_admin then
    return false;
  end if;

  select exists (
    select 1
    from public.org_members om
    where om.org_id = org_id and om.user_id = user_id and om.role = 'owner'
  ) into is_owner;

  if role = 'member' then
    return true;
  elsif role in ('admin', 'owner') and is_owner then
    return true;
  else
    return false;
  end if;
end;
$$ language plpgsql security definer;

