CREATE OR REPLACE FUNCTION enforce_invoice_update_rules()
RETURNS TRIGGER AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.status != OLD.status THEN
      IF OLD.status = 'draft' THEN
        IF NEW.status != 'sent' THEN
          RAISE EXCEPTION 'Only draft can be changed to sent';
        END IF;
      ELSIF OLD.status = 'sent' THEN
        IF NEW.status NOT IN ('paid', 'void') THEN
          RAISE EXCEPTION 'Sent status can only be changed to paid or void';
        END IF;
      END IF;
    END IF;
    IF NEW.created_by != OLD.created_by THEN
      RAISE EXCEPTION 'Cannot change created_by';
    END IF;
    IF OLD.status != 'draft' AND (NEW.customer != OLD.customer OR NEW.amount != OLD.amount) THEN
      RAISE EXCEPTION 'Cannot change customer or amount after draft';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER enforce_invoice_update_rules
BEFORE UPDATE ON public.invoices
