```sql
alter table public.events enable row level security;
alter table public.delegations enable row level security;

create policy events_authenticated_select on public.events for select using (
  owner_id = auth.uid() OR
  (exists (
    select 1
    from delegations d
    where d.grantor_id = owner_id
      and d.delegate_id = auth.uid()
      and (d.expires_at is null or d.expires_at > now())
  ) AND is_private = false
);

create policy events_authenticated_insert on public.events for insert with check (
  (owner_id = auth.uid()) OR
  (exists (
    select 1
    from delegations d
    where d.grantor_id = owner_id
      and d.delegate_id = auth.uid()
      and d.can_edit = true
      and (d.expires_at is null or d.expires_at > now())
  ) AND is_private = false)
);

create policy events_authenticated_update on public.events for update using (
  owner_id = auth.uid() OR
  (exists (
    select 1
    from delegations d
    where d.grantor_id = owner_id
      and d.delegate_id = auth.uid()
      and d.can_edit = true
      and (d.expires_at is null or d.expires_at > now())
  )) AND (NEW.is_private IS FALSE OR owner_id = auth.uid())
);

create policy events_authenticated_delete on public.events for delete using (
  owner_id = auth.uid() OR
  (exists (
    select 1
    from delegations d
    where d.grantor_id = owner_id
      and d.delegate_id = auth.uid()
      and d.can_edit = true
      and (d.expires_at is null or d.expires_at > now())
  ))
);

create policy delegations_authenticated_insert on public.delegations for insert with check (grantor_id = auth.uid());

create policy delegations_authenticated_select on public.delegations for select using (grantor_id = auth.uid() OR delegate_id = auth.uid());

create policy delegations_authenticated_update on public.delegations for update using (grantor_id = auth.uid());

create policy delegations_authenticated_delete on public.delegations for delete using (grantor_id = auth.uid());

create or replace view public.busy_slots as
select owner_id, starts_at, ends_at
from events
where owner_id = auth.uid()
or exists (
  select 1
  from delegations d
  where d.grantor_id = events.owner_id
    and d.delegate_id = auth.uid()
    and (d.expires_at is null or d.expires_at > now())
);

grant select on public.busy_slots to authenticated;
revoke select on public.busy_slots from anon;
grant select on public.busy_slots to service_role;
```
